  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': 	ประยุกต์ใช้ความรู้ทางด้านคณิตศาสตร์ พื้นฐานทางด้านวิศวกรรมศาสตร์ ในการกำหนดกรอบความคิด กระบวนการ หรือระบบงานสำหรับการวิเคราะห์ แก้ไขปัญหา และประเมินผลงานและปัญหาทางวิศวกรรม วิศวกรรมในการทำงานได้อย่างถูกต้อง |  5 (ยอดเยี่ยม): ประยุกต์ใช้ความรู้ทางด้านคณิตศาสตร์ พื้นฐานทางด้านวิศวกรรมศาสตร์ ในการกำหนดกรอบความคิด กระบวนการ หรือระบบงานสำหรับการวิเคราะห์ แก้ไขปัญหา และประเมินผลงานและปัญหาทางวิศวกรรมในการทำงานได้อย่างถูกต้อง  4 (ดีมาก): ประยุกต์ใช้ความรู้ทางด้านคณิตศาสตร์ พื้นฐานทางด้านวิศวกรรมศาสตร์ ในการกำหนดกรอบความคิด กระบวนการ หรือระบบงานสำหรับการวิเคราะห์ แก้ไขปัญหา และประเมินผลงานและปัญหาทางวิศวกรรมในการทำงานได้ไม่กระทบต่อคุณภาพโดยรวม  3 (ดี): ประยุกต์ใช้ความรู้ทางด้านคณิตศาสตร์ พื้นฐานทางด้านวิศวกรรมศาสตร์ ในการกำหนดกรอบความคิด กระบวนการ หรือระบบงานสำหรับการวิเคราะห์ แก้ไขปัญหา และประเมินผลงานและปัญหาทางวิศวกรรมโดยยังขาดความสมบูรณ์ในบางส่วน   2 (พอใช้): ประยุกต์ใช้ความรู้ทางด้านคณิตศาสตร์ พื้นฐานทางด้านวิศวกรรมศาสตร์ ในการกำหนดกรอบความคิด กระบวนการ หรือระบบงานสำหรับการวิเคราะห์ แก้ไขปัญหา และประเมินผลงานและปัญหาทางวิศวกรรม โดยต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถประยุกต์ใช้ความรู้ทางด้านคณิตศาสตร์ พื้นฐานทางด้านวิศวกรรมศาสตร์ ในการกำหนดกรอบความคิด กระบวนการ หรือระบบงานสำหรับการวิเคราะห์ แก้ไขปัญหา และประเมินผลงานและปัญหาทางวิศวกรรม วิศวกรรมในการทำงานได้อย่างถูกต้อง', NULL, 'LO1', 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': อธิบาย และประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมโยธาต่อบริบทของทางสังคม ชีวอนามัย ความปลอดภัย กฎหมาย สิ่งแวดล้อม และการพัฒนาที่ยั่งยืน |   5 (ยอดเยี่ยม): อธิบาย และประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมโยธาต่อบริบทของทางสังคม ชีวอนามัย ความปลอดภัย กฎหมาย สิ่งแวดล้อม และการพัฒนาที่ยั่งยืนในการทำงานได้อย่างถูกต้อง   4 (ดีมาก): อธิบาย และประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมโยธาต่อบริบทของทางสังคม ชีวอนามัย ความปลอดภัย กฎหมาย สิ่งแวดล้อม และการพัฒนาที่ยั่งยืนในการทำงานได้ไม่กระทบต่อคุณภาพโดยรวม   3 (ดี): อธิบาย และประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมโยธาต่อบริบทของทางสังคม ชีวอนามัย ความปลอดภัย กฎหมาย สิ่งแวดล้อม และการพัฒนาที่ยั่งยืนโดยยังขาดความสมบูรณ์ในบางส่วน   2 (พอใช้): อธิบาย และประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมโยธาต่อบริบทของทางสังคม ชีวอนามัย ความปลอดภัย กฎหมาย สิ่งแวดล้อม และการพัฒนาที่ยั่งยืนโดยต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถอธิบาย และประเมินผลกระทบของการดำเนินงานด้านวิศวกรรมโยธาต่อบริบทของทางสังคม ชีวอนามัย ความปลอดภัย กฎหมาย สิ่งแวดล้อม และการพัฒนาที่ยั่งยืน', NULL, 'LO2', 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
  VALUES (t_id, 'ด้านทักษะ (Skills)', NULL, 'skills'::domain_type, 2)
  RETURNING id INTO s_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ออกแบบการก่อสร้างหรือกระบวนการทางวิศวกรรม ตามความต้องการและเป็นไปตามข้อกำหนดงาน โดยคำนึงถึงข้อกำหนดด้านกฎหมาย สังคม ความปลอดภัย และมาตรฐานการปฏิบัติวิชาชีพ |   5 (ยอดเยี่ยม): ออกแบบการก่อสร้างหรือกระบวนการทางวิศวกรรม ตามความต้องการและเป็นไปตามข้อกำหนดงาน โดยคำนึงถึงข้อกำหนดด้านกฎหมาย สังคม ความปลอดภัย และมาตรฐานการปฏิบัติวิชาชีพในการทำงานได้อย่างถูกต้อง   4 (ดีมาก): ออกแบบการก่อสร้างหรือกระบวนการทางวิศวกรรม ตามความต้องการและเป็นไปตามข้อกำหนดงาน โดยคำนึงถึงข้อกำหนดด้านกฎหมาย สังคม ความปลอดภัย และมาตรฐานการปฏิบัติวิชาชีพในการทำงานได้ไม่กระทบต่อคุณภาพโดยรวม   3 (ดี): ออกแบบการก่อสร้างหรือกระบวนการทางวิศวกรรม ตามความต้องการและเป็นไปตามข้อกำหนดงาน โดยคำนึงถึงข้อกำหนดด้านกฎหมาย สังคม ความปลอดภัย และมาตรฐานการปฏิบัติวิชาชีพโดยยังขาดความสมบูรณ์ในบางส่วน   2 (พอใช้): ออกแบบการก่อสร้างหรือกระบวนการทางวิศวกรรม ตามความต้องการและเป็นไปตามข้อกำหนดงาน โดยคำนึงถึงข้อกำหนดด้านกฎหมาย สังคม ความปลอดภัย และมาตรฐานการปฏิบัติวิชาชีพโดยต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถออกแบบการก่อสร้างหรือกระบวนการทางวิศวกรรม ตามความต้องการและเป็นไปตามข้อกำหนดงาน โดยคำนึงถึงข้อกำหนดด้านกฎหมาย สังคม ความปลอดภัย และมาตรฐานการปฏิบัติวิชาชีพ', NULL, 'LO3', 'single_choice'::question_type, true, 1)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': มีความเป็นผู้ประกอบการ สามารถอธิบาย วิเคราะห์ และประเมินเศรษฐศาสตร์ การลงทุน สัญญา และการบริหารงานวิศวกรรมโดยคำนึงถึงความเสี่ยงและการเปลี่ยนแปลง |   5 (ยอดเยี่ยม): มีความเป็นผู้ประกอบการ สามารถอธิบาย วิเคราะห์ และประเมินเศรษฐศาสตร์ การลงทุน สัญญา และการบริหารงานวิศวกรรมโดยคำนึงถึงความเสี่ยงและการเปลี่ยนแปลง   4 (ดีมาก): มีความเป็นผู้ประกอบการ สามารถอธิบาย วิเคราะห์ และประเมินเศรษฐศาสตร์ การลงทุน สัญญา และการบริหารงานวิศวกรรมโดยคำนึงถึงความเสี่ยงและการเปลี่ยนแปลงในการทำงานได้ไม่กระทบต่อคุณภาพโดยรวม   3 (ดี): มีความเป็นผู้ประกอบการ สามารถอธิบาย วิเคราะห์ และประเมินเศรษฐศาสตร์ การลงทุน สัญญา และการบริหารงานวิศวกรรมโดยคำนึงถึงความเสี่ยงและการเปลี่ยนแปลงโดยยังขาดความสมบูรณ์ในบางส่วน   2 (พอใช้): มีความเป็นผู้ประกอบการ สามารถอธิบาย วิเคราะห์ และประเมินเศรษฐศาสตร์ การลงทุน สัญญา และการบริหารงานวิศวกรรมโดยคำนึงถึงความเสี่ยงและการเปลี่ยนแปลงโดยต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถมีความเป็นผู้ประกอบการ สามารถอธิบาย วิเคราะห์ และประเมินเศรษฐศาสตร์ การลงทุน สัญญา และการบริหารงานวิศวกรรมโดยคำนึงถึงความเสี่ยงและการเปลี่ยนแปลง', NULL, 'LO4', 'single_choice'::question_type, true, 2)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': มีทักษะตั้งสมมติฐาน ระบุ สืบค้น อ้างอิง ทำการทดลอง วิเคราะห์ข้อมูลและออกแบบการทดลองงานทางด้านวิศวกรรม และใช้เทคนิควิธี อุปกรณ์เครื่องมือทางวิศวกรรมและเทคโนโลยีสารสนเทศที่เหมาะกับงานทางด้านวิศวกรรมโยธา |   5 (ยอดเยี่ยม): มีทักษะตั้งสมมติฐาน ระบุ สืบค้น อ้างอิง ทำการทดลอง วิเคราะห์ข้อมูลและออกแบบการทดลองงานทางด้านวิศวกรรม และใช้เทคนิควิธี อุปกรณ์เครื่องมือทางวิศวกรรมและเทคโนโลยีสารสนเทศที่เหมาะกับงานทางด้านวิศวกรรมโยธา   4 (ดีมาก): มีทักษะตั้งสมมติฐาน ระบุ สืบค้น อ้างอิง ทำการทดลอง วิเคราะห์ข้อมูลและออกแบบการทดลองงานทางด้านวิศวกรรม และใช้เทคนิควิธี อุปกรณ์เครื่องมือทางวิศวกรรมและเทคโนโลยีสารสนเทศที่เหมาะกับงานทางด้านวิศวกรรมโยธาในการทำงานได้ไม่กระทบต่อคุณภาพโดยรวม   3 (ดี): มีทักษะตั้งสมมติฐาน ระบุ สืบค้น อ้างอิง ทำการทดลอง วิเคราะห์ข้อมูลและออกแบบการทดลองงานทางด้านวิศวกรรม และใช้เทคนิควิธี อุปกรณ์เครื่องมือทางวิศวกรรมและเทคโนโลยีสารสนเทศที่เหมาะกับงานทางด้านวิศวกรรมโยธา โดยยังขาดความสมบูรณ์ในบางส่วน   2 (พอใช้): มีทักษะตั้งสมมติฐาน ระบุ สืบค้น อ้างอิง ทำการทดลอง วิเคราะห์ข้อมูลและออกแบบการทดลองงานทางด้านวิศวกรรม และใช้เทคนิควิธี อุปกรณ์เครื่องมือทางวิศวกรรมและเทคโนโลยีสารสนเทศที่เหมาะกับงานทางด้านวิศวกรรมโยธา โดยต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถมีทักษะตั้งสมมติฐาน ระบุ สืบค้น อ้างอิง ทำการทดลอง วิเคราะห์ข้อมูลและออกแบบการทดลองงานทางด้านวิศวกรรม และใช้เทคนิควิธี อุปกรณ์เครื่องมือทางวิศวกรรมและเทคโนโลยีสารสนเทศที่เหมาะกับงานทางด้านวิศวกรรมโยธา', NULL, 'LO5', 'single_choice'::question_type, true, 3)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': มีทักษะการสื่อสารภาษาไทยและภาษาอังกฤษในการทำงานด้านวิศวกรรมโยธา ทั้งการฟัง พูด อ่าน เขียน และเสนอผลงานได้ |   5 (ยอดเยี่ยม): มีทักษะการสื่อสารภาษาไทยและภาษาอังกฤษในการทำงานด้านวิศวกรรมโยธา ทั้งการฟัง พูด อ่าน เขียน และเสนอผลงานได้   4 (ดีมาก): ทักษะการสื่อสารภาษาไทยและภาษาอังกฤษในการทำงานด้านวิศวกรรมโยธา ทั้งการฟัง พูด อ่าน เขียน และเสนอผลงานในการทำงานได้ไม่กระทบต่อคุณภาพโดยรวม   3 (ดี): มีทักษะตั้งสมมติฐาน ระบุ สืบค้น อ้างอิง ทำการทดลอง วิเคราะห์ข้อมูลและออกแบบการทดลองงานทางด้านวิศวกรรม และใช้เทคนิควิธี อุปกรณ์เครื่องมือทางวิศวกรรมและเทคโนโลยีสารสนเทศที่เหมาะกับงานทางด้านวิศวกรรมโยธา โดยยังขาดความสมบูรณ์ในบางส่วน   2 (พอใช้): ทักษะการสื่อสารภาษาไทยและภาษาอังกฤษในการทำงานด้านวิศวกรรมโยธา ทั้งการฟัง พูด อ่าน เขียน และเสนอผลงานโดยต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่สามารถสื่อสารภาษาไทยและภาษาอังกฤษในการทำงานด้านวิศวกรรมโยธา ทั้งการฟัง พูด อ่าน เขียน และเสนอผลงาน', NULL, 'LO6', 'single_choice'::question_type, true, 4)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': มีทักษะการดูแลสุขภาพทางกายและจิตใจ และปฏิบัติตนเพื่อเตรียมพร้อมด้านร่างกายและจิตใจต่อสิ่งแวดล้อมและสถานการณ์ที่มีการเปลี่ยนแปลง |   5 (ยอดเยี่ยม): มีทักษะการดูแลสุขภาพทางกายและจิตใจ และปฏิบัติตนเพื่อเตรียมพร้อมด้านร่างกายและจิตใจต่อสิ่งแวดล้อมและสถานการณ์ที่มีการเปลี่ยนแปลง   4 (ดีมาก): มีทักษะการดูแลสุขภาพทางกายและจิตใจ และปฏิบัติตนเพื่อเตรียมพร้อมด้านร่างกายและจิตใจต่อสิ่งแวดล้อมและสถานการณ์ที่มีการเปลี่ยนแปลงโดยไม่กระทบต่อคุณภาพโดยรวม   3 (ดี): มีทักษะการดูแลสุขภาพทางกายและจิตใจ และปฏิบัติตนเพื่อเตรียมพร้อมด้านร่างกายและจิตใจต่อสิ่งแวดล้อมและสถานการณ์ที่มีการเปลี่ยนแปลง โดยยังขาดความสมบูรณ์ในบางส่วน   2 (พอใช้): มีทักษะการดูแลสุขภาพทางกายและจิตใจ และปฏิบัติตนเพื่อเตรียมพร้อมด้านร่างกายและจิตใจต่อสิ่งแวดล้อมและสถานการณ์ที่มีการเปลี่ยนแปลงโดยต้องการคำแนะนำอย่างใกล้ชิด   1 (ต้องปรับปรุง): ไม่มีทักษะการดูแลสุขภาพทางกายและจิตใจ และปฏิบัติตนเพื่อเตรียมพร้อมด้านร่างกายและจิตใจต่อสิ่งแวดล้อมและสถานการณ์ที่มีการเปลี่ยนแปลง', NULL, 'LO7', 'single_choice'::question_type, true, 5)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': พัฒนาตนเองอย่างต่อเนื่อง |  5 (ยอดเยี่ยม): ใฝ่เรียน ใฝ่รู้ และพัฒนาตนเองอย่างต่อเนื่อง  4 (ดีมาก): ใฝ่เรียน ใฝ่รู้ และพัฒนาตนเองอย่างต่อเนื่องได้บางส่วนไม่กระทบต่อคุณภาพโดยรวม  3 (ดี): พัฒนาตนเองอย่างต่อเนื่องโดยยังขาดความสมบูรณ์ในบางส่วน  2 (พอใช้): พัฒนาตนเองอย่างต่อเนื่องโดยต้องการคำแนะนำอย่างใกล้ชิด  1 (ต้องปรับปรุง): ไม่สามารถพัฒนาตนเองอย่างต่อเนื่อง', NULL, 'LO8', 'single_choice'::question_type, true, 6)
  RETURNING id INTO q_id;
  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, ': ปฏิบัติตนตามกฎกติกาของสังคมและจรรยาบรรณแห่งวิชาชีพตามกรอบมาตรฐานการปฏิบัติวิชาชีพวิศวกรรมโยธา |  5 (ยอดเยี่ยม): ปฏิบัติตนตามกฎกติกาของสังคมและจรรยาบรรณแห่งวิชาชีพตามกรอบมาตรฐานการปฏิบัติวิชาชีพวิศวกรรมโยธา  4 (ดีมาก): ปฏิบัติตนตามกฎกติกาของสังคมและจรรยาบรรณแห่งวิชาชีพตามกรอบมาตรฐานการปฏิบัติวิชาชีพวิศวกรรมโยธาได้บางส่วนไม่กระทบต่อคุณภาพโดยรวม  3 (ดี): ปฏิบัติตนตามกฎกติกาของสังคมและจรรยาบรรณแห่งวิชาชีพตามกรอบมาตรฐานการปฏิบัติวิชาชีพวิศวกรรมโยธาโดยยังขาดความสมบูรณ์ในบางส่วน  2 (พอใช้): ปฏิบัติตนตามกฎกติกาของสังคมและจรรยาบรรณแห่งวิชาชีพตามกรอบมาตรฐานการปฏิบัติวิชาชีพวิศวกรรมโยธาโดยต้องการคำแนะนำอย่างใกล้ชิด  1 (ต้องปรับปรุง): ไม่ปฏิบัติตนตามกฎกติกาของสังคมและจรรยาบรรณแห่งวิชาชีพตามกรอบมาตรฐานการปฏิบัติวิชาชีพวิศวกรรมโยธา', NULL, 'LO9', 'single_choice'::question_type, true, 7)
  RETURNING id INTO q_id;
  INSERT INTO public.assessment_sections (template_id, title_th, title_en, domain_type, sequence)
