  INSERT INTO public.evaluation_questions (template_id, section_id, text, text_en, lo_code, question_type, is_required, sequence)
  VALUES (t_id, s_id, 'มีภาวะผู้นํา และคุณธรรมจริยธรรม ผลลัพธ์การเรียนรู้ของวิชาสหกิจศึกษา (Course Learning Outcome: CLO) CLO1 วิเคราะห์ความสัมพันธ์ระหว่างปัจจัยสิ่งแวดล้อมต่อสุขภาพของมนุษย์ในการปฏิบัติงานสหกิจศึกษา CLO2 ตรวจสอบ เฝ้าระวัง และประเมินปัจจัยสิ่งแวดล้อมที่ส่งผลกระทบต่อสุขภาพมนุษย์ในการปฏิบัติงานสหกิจ ศึกษา CLO3 เสนอมาตรการป้องกันและควบคุมปัจจัยเสี่ยงต่อสุขภาพในการปฏิบัติงานสหกิจศึกษา CLO4 ปฏิบัติงานสหกิจศึกษาด้านอนามัยสิ่งแวดล้อมได้ตามวัตถุประสงค์และความต้องการของสถานประกอบการ CLO5 ออกแบบกระบวนการและให้คำปรึกษาด้านอนามัยสิ่งแวดล้อมให้กับสถานประกอบการได้อย่างถูกต้องตาม หลักวิชาการ CLO6 สื่อสารผลการปฏิบัติสหกิจและโครงงานได้อย่างเข้าใจ CLO7 แสดงออกถึงความเป็นผู้นำและปฏิบัติตัวตามวัฒนธรรมขององค์กรอย่างมีคุณธรรมและจริยธรรม แบบประเมินผลการปฏิบัติสหกิจศึกษาตามผลลัพธ์การเรียนรู้ที่คาดหวัง ผลการเรียนรู้ที่คาดหวัง ดีมาก ดี พอใช้ ต้องปรับปรุง (4 คะแนน) (3 คะแนน) (2 คะแนน) (1 คะแนน) CLO1 วิเคราะห์ วิเคราะหค์ วามสัมพันธ์ วิเคราะหไ์ ด้ถูกต้อง วิเคราะหไ์ ด้บางส่วน ไม่สามารถวเิคราะห์ ความสัมพันธร์ ะหว่างปัจจยั ได้อย่างถูกต้อง ในภาพรวม แต่ขาด แต่ยังขาดความ ความสัมพันธไ์ ด้ สิ่งแวดล้อมต่อสุขภาพของ ครอบคลมุ และแสดง รายละเอียดในบาง เชื่อมโยงที่ชัดเจน อย่างถูกต้องหรือ มนุษย์ในการปฏิบตั ิงานสห ความเข้าใจเชิงลึก จุด เหมาะสม กิจศึกษา CLO2 ตรวจสอบ เฝ้าระวัง ตรวจสอบ เฝ้าระวัง ตรวจสอบและ ตรวจสอบได้บางส่วน ไม่สามารถ และประเมินปจั จัย และประเมินปจั จัย ประเมินไดด้ ี แต่ขาด แต่ยังขาดการประเมิน ตรวจสอบและ สิ่งแวดล้อมทสี่ ่งผลกระทบ สิ่งแวดล้อมได้อย่าง ความละเอียดในบาง ที่เหมาะสมหรือ ประเมินได้อยา่ ง' || 'ต่อสุขภาพมนุษย์ในการ ถูกต้อง ครอบคลุม และ ประเด็น ครบถ้วน ถูกต้อง ปฏิบัติงานสหกจิ ศึกษา ครบถ้วน ผลการเรียนรู้ที่คาดหวัง ดีมาก ดี พอใช้ ต้องปรับปรุง (4 คะแนน) (3 คะแนน) (2 คะแนน) (1 คะแนน) CLO3 เสนอมาตรการ เสนอมาตรการที่ชัดเจน เสนอมาตรการไดด้ ี เสนอมาตรการได้ ไม่สามารถเสนอ ป้องกันและควบคุมปัจจัย ใช้ได้จริง และมีความ ', NULL, 'PLO7', 'single_choice'::question_type, true, 7)
  RETURNING id INTO q_id;
END $$;


DO $$ DECLARE t_id uuid; s_id uuid; q_id uuid; BEGIN
